  // task 100 (parcel 6) — Dictionary / Array returns on any audited arg shape. Same arg cells as
  // kanama_ios_godot_ptrcall; the C entry ptrcalls into the container cell and serializes it ONCE
  // into a self-describing blob (records of [variant_type][byteLen][bytes], nested containers as
  // nested blobs, String/StringName keys as utf8). A blob longer than the inline buffer is parked
  // C-side and drained whole; nothing is truncated and the method is not re-issued. The decode is
  // the same scalar set as decodeVariantScalarReturn plus the nested containers and packed
  // arrays (task 121); other types surface null. Desktop parity: BuiltinTypes.readDictionaryScalars
  // keeps String keys only and
  // decodes values with variantToScalar; readArrayDictionaries maps the non-Map elements away.
  private class ContainerBlob(private val b: ByteArray, private var off: Int) {
    private fun i32(): Int {
      val v =
        (b[off].toInt() and 0xFF) or
          ((b[off + 1].toInt() and 0xFF) shl 8) or
          ((b[off + 2].toInt() and 0xFF) shl 16) or
          ((b[off + 3].toInt() and 0xFF) shl 24)
      off += 4
      return v
    }

    private fun i64At(o: Int): Long {
      var v = 0L
      for (k in 7 downTo 0) v = (v shl 8) or (b[o + k].toLong() and 0xFF)
      return v
    }

    private fun f32At(o: Int): Float = Float.fromBits(i32LE(b, o))

    fun record(): Any? {
      val vt = i32()
      val len = i32()
      val start = off
      val end = start + len
      val value: Any? =
        when (vt) {
          VT_BOOL -> len >= 1 && b[start].toInt() != 0
          VT_INT -> if (len >= 8) i64At(start) else 0L
          VT_FLOAT -> if (len >= 8) Double.fromBits(i64At(start)) else 0.0
          VT_STRING,
          VT_STRING_NAME -> b.decodeToString(start, end)
          VT_NODE_PATH -> NodePath(b.decodeToString(start, end))
          // Object elements decode to a GodotObject wrapper, as desktop's variantToAny does (task
          // 115); callers used to receive the raw handle here and re-wrap it per call site. They
          // are BORROWED wrappers, except in a blob of the Object.call family (task 122 item 3):
          // there the C side retained each RefCounted element while the container still held it
          // and marked the record with a ninth byte, and the element is the owning wrapper of
          // that +1 (close() releases it, or the garbage collector does).
          VT_OBJECT ->
            when {
              len < 8 -> null
              len >= 9 && b[start + 8].toInt() != 0 ->
                RefCounted.owned(RefCounted(GodotHandle(MemorySegment.ofAddress(i64At(start)))))
              else -> GodotObject.wrap(MemorySegment.ofAddress(i64At(start)))
            }
          VT_VECTOR2 -> if (len >= 8) Vector2.raw(f32At(start), f32At(start + 4)) else null
          VT_VECTOR2I -> if (len >= 8) Vector2i(i32LE(b, start), i32LE(b, start + 4)) else null
          VT_VECTOR3 ->
            if (len >= 12) Vector3.raw(f32At(start), f32At(start + 4), f32At(start + 8)) else null
          VT_COLOR ->
            if (len >= 16)
              Color.raw(f32At(start), f32At(start + 4), f32At(start + 8), f32At(start + 12))
            else null
          VT_ARRAY -> if (len >= 4) ContainerBlob(b, start).array() else null
          VT_DICTIONARY -> if (len >= 4) ContainerBlob(b, start).dictionary() else null
          // task 121 — packed kinds: contiguous element bytes (count = byteLen / element size,
          // real_t = float32; byteLen 0 = empty list, as for a genuinely empty array) or, for
          // strings, the [count]([len][utf8])* layout parseBlobRecords already reads. Kotlin types
          // match desktop's BuiltinTypes.readPacked*Array: List<Int/Long/Float/Double/Vector2/
          // Vector3/Color/String>; PackedVector4Array -> List<Vector4> (task 122).
          VT_PACKED_STRING_ARRAY_TYPE ->
            if (len >= 4)
              parseBlobRecords(b.copyOfRange(start, end)) { bb, oo, ll ->
                bb.decodeToString(oo, oo + ll)
              }
            else null
          VT_PACKED_INT32_ARRAY -> List(len / 4) { i32LE(b, start + it * 4) }
          VT_PACKED_INT64_ARRAY -> List(len / 8) { i64At(start + it * 8) }
          VT_PACKED_FLOAT32_ARRAY -> List(len / 4) { f32At(start + it * 4) }
          VT_PACKED_FLOAT64_ARRAY -> List(len / 8) { Double.fromBits(i64At(start + it * 8)) }
          VT_PACKED_VECTOR2_ARRAY ->
            List(len / 8) {
              val o = start + it * 8
              Vector2.raw(f32At(o), f32At(o + 4))
            }
          VT_PACKED_VECTOR3_ARRAY ->
            List(len / 12) {
              val o = start + it * 12
              Vector3.raw(f32At(o), f32At(o + 4), f32At(o + 8))
            }
          VT_PACKED_COLOR_ARRAY ->
            List(len / 16) {
              val o = start + it * 16
              Color.raw(f32At(o), f32At(o + 4), f32At(o + 8), f32At(o + 12))
            }
          VT_PACKED_VECTOR4_ARRAY ->
            List(len / 16) {
              val o = start + it * 16
              Vector4.raw(f32At(o), f32At(o + 4), f32At(o + 8), f32At(o + 12))
            }
          // task 100 parcel 10: a PackedByteArray element carries its raw bytes.
          VT_PACKED_BYTE_ARRAY -> b.copyOfRange(start, end)
          VT_RID_TYPE -> if (len >= 8) RID(i64At(start)) else null
          // The raw value kinds (Vector3i ... Projection) carry their Godot bytes, decoded like a
          // scalar return of the same type. Nil, Callable and Signal carry none and are null, as
          // on desktop; the shim reports any other type instead of encoding it.
          else -> if (len > 0) rawValue(vt, start, len) else null
        }
      off = end
      return value
    }

    private fun rawValue(variantType: Int, start: Int, len: Int): Any? = memScoped {
      val raw = allocIosRawValue()
      val n = minOf(len, net.multigesture.kanama.ios.IOS_RAW_VALUE_MAX_BYTES)
      for (i in 0 until n) raw[i] = b[start + i]
      net.multigesture.kanama.ios.decodeIosRawVariant(variantType, raw)
    }

    fun array(): List<Any?> {
      val count = i32()
      val out = ArrayList<Any?>(if (count > 0) count else 0)
      repeat(count) { out.add(record()) }
      return out
    }

    fun dictionary(): Map<String, Any?> {
      val count = i32()
      val out = LinkedHashMap<String, Any?>(if (count > 0) count else 0)
      repeat(count) {
        val klen = i32()
        val key = b.decodeToString(off, off + klen)
        off += klen
        out[key] = record()
      }
      return out
    }
  }

  /**
   * One whole blob record (`[int32 variant_type][int32 byteLen][payload]`), decoded as a container
   * return is: the inbound container argument of a signal lambda or a script method (task 122 item
   * 4, `KANAMA_IOS_PT_VARIANT_RECORD`). Object elements are borrowed wrappers.
   */
  internal fun decodeVariantRecord(record: ByteArray): Any? =
    if (record.size >= 8) ContainerBlob(record, 0).record() else null

  private fun MemScope.ptrcallContainerBlob(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
    containerKind: Int,
  ): ByteArray {
    val inlineCap = 4096L
    val inline = allocArray<ByteVar>(inlineCap)
    val total =
      ptrcallRetContainerBlobDispatch(
        methodBind.address(),
        instance.address(),
        argTypes,
        argPtrs,
        argCount,
        containerKind,
        inline,
        inlineCap,
      )
    return when {
      total < 4L -> ByteArray(0)
      total <= inlineCap -> inline.readBytes(total.toInt())
      else -> {
        val full = allocArray<ByteVar>(total)
        val got = kanama_ios_godot_take_pending_container_blob(full, total)
        if (got < 4L) ByteArray(0) else full.readBytes(minOf(got, total).toInt())
      }
    }
  }

  fun ptrcallRetDictionary(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
  ): Map<String, Any?> = memScoped {
    val bytes =
      ptrcallContainerBlob(methodBind, instance, argTypes, argPtrs, argCount, VT_DICTIONARY)
    if (bytes.size < 4) emptyMap() else ContainerBlob(bytes, 0).dictionary()
  }

  fun ptrcallRetArray(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
  ): List<Any?> = memScoped {
    val bytes = ptrcallContainerBlob(methodBind, instance, argTypes, argPtrs, argCount, VT_ARRAY)
    if (bytes.size < 4) emptyList() else ContainerBlob(bytes, 0).array()
  }

  // Array[Dictionary] -> List<Map<String, Any?>>: the typed array is a plain Array at the ptrcall
  // level; non-Dictionary elements are dropped, as desktop's readArrayDictionaries does.
  fun ptrcallRetDictionaryList(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
  ): List<Map<String, Any?>> =
    ptrcallRetArray(methodBind, instance, argTypes, argPtrs, argCount).mapNotNull {
      @Suppress("UNCHECKED_CAST")
      it as? Map<String, Any?>
    }

  // Array[Array] -> List<List<Any?>> (task 100 parcel 10): non-Array elements are dropped, as
  // desktop's readArrayArrays does. A PackedByteArray inside decodes to a ByteArray.
  fun ptrcallRetArrayList(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
  ): List<List<Any?>> =
    ptrcallRetArray(methodBind, instance, argTypes, argPtrs, argCount).mapNotNull {
      @Suppress("UNCHECKED_CAST")
      it as? List<Any?>
    }

  // task 100 (parcel 5) — string-list / typed-Array returns on any audited arg shape. Same arg
  // cells
  // as kanama_ios_godot_ptrcall; the C entry ptrcalls ONCE into the array cell and encodes the
  // length-prefixed blob the no-arg read-backs use ([int32 count]([int32 len][bytes])*), delivering
  // it whole: inline when it fits 4 KiB, otherwise parked C-side and drained by the second call.
  // One blob read-back + one record parser; the per-kind decoders below only interpret the bytes.
  private fun MemScope.ptrcallArrayBlob(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
    blobKind: Int,
    elemKind: Int,
  ): ByteArray {
    val inlineCap = 4096L
    val inline = allocArray<ByteVar>(inlineCap)
    val total =
      ptrcallRetArrayBlobDispatch(
        methodBind.address(),
        instance.address(),
        argTypes,
        argPtrs,
        argCount,
        blobKind,
        elemKind,
        inline,
        inlineCap,
      )
    return when {
      total < 4L -> ByteArray(0)
      total <= inlineCap -> inline.readBytes(total.toInt())
      else -> {
        val full = allocArray<ByteVar>(total)
        val got = kanama_ios_godot_take_pending_blob(full, total)
        if (got < 4L) ByteArray(0) else full.readBytes(minOf(got, total).toInt())
      }
    }
  }

  private fun <T> parseBlobRecords(bytes: ByteArray, parse: (ByteArray, Int, Int) -> T): List<T> {
    if (bytes.size < 4) return emptyList()
    val count = i32LE(bytes, 0)
    var off = 4
    val out = ArrayList<T>(if (count > 0) count else 0)
    repeat(count) {
      val len = i32LE(bytes, off)
      off += 4
      out.add(parse(bytes, off, len))
      off += len
    }
    return out
  }

  private fun i64LE(b: ByteArray, o: Int): Long {
    var v = 0L
    for (k in 7 downTo 0) v = (v shl 8) or (b[o + k].toLong() and 0xFF)
    return v
  }

  private fun <T> MemScope.typedList(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
    elemKind: Int,
    parse: (ByteArray, Int, Int) -> T,
  ): List<T> =
    parseBlobRecords(
      ptrcallArrayBlob(
        methodBind,
        instance,
        argTypes,
        argPtrs,
        argCount,
        BLOB_TYPED_ARRAY,
        elemKind,
      ),
      parse,
    )

  fun ptrcallRetPackedStringList(
    methodBind: MemorySegment,
    instance: MemorySegment,
    argTypes: CValuesRef<IntVar>?,
    argPtrs: CValuesRef<COpaquePointerVar>?,
    argCount: Int,
  ): List<String> = memScoped {
    parseBlobRecords(
      ptrcallArrayBlob(
        methodBind,
        instance,
        argTypes,
        argPtrs,
        argCount,
        BLOB_PACKED_STRING_ARRAY,
        0,
      )
    ) { b, o, l ->
      b.decodeToString(o, o + l)
    }
  }

