    typedList(methodBind, instance, argTypes, argPtrs, argCount, PT_PACKED_STRING_ARRAY) { b, o, l
      ->
      parseBlobRecords(b.copyOfRange(o, o + l)) { bb, oo, ll -> bb.decodeToString(oo, oo + ll) }
    }
  }

  actual fun ptrcallNoArgsRetNodePath(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): NodePath = NodePath(ptrcallRetUtf8(methodBind, instance, null, null, 0, PT_NODE_PATH))

  // The no-arg Packed*Array returns use the single-call any-arg helpers (task 129 D): the method
  // runs once, a long array is parked C-side and drained whole.
  actual fun ptrcallNoArgsRetPackedInt32List(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): List<Int> = ptrcallRetPackedInt32List(methodBind, instance, null, null, 0)

  actual fun ptrcallNoArgsRetPackedStringList(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): List<String> = ptrcallRetPackedStringList(methodBind, instance, null, null, 0)

  actual fun ptrcallNoArgsRetPackedFloat32List(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): List<Float> = ptrcallRetPackedFloat32List(methodBind, instance, null, null, 0)

  // PackedFloat32Array arg (build-from-list): copy the List into a flat float buffer; the C
  // helper builds the array (constructor + push_back) and ptrcalls the single-arg void method.
  actual fun ptrcallWithPackedFloat32ListArg(
    methodBind: MemorySegment,
    instance: MemorySegment,
    values: List<Float>,
  ) = memScoped {
    val n = values.size
    val buf = allocArray<FloatVar>(if (n > 0) n else 1)
    for (i in 0 until n) buf[i] = values[i]
    ptrcallWithPackedFloat32ArgDispatch(methodBind.address(), instance.address(), buf, n.toLong())
    Unit
  }

  // ---- PackedByteArray traffic + static-method dispatch ----
  // Bulk byte payloads (heightmaps, road masks, image readback) and Godot STATIC methods
  // (FileAccess.get_file_as_bytes/open, Image.create_from_data, ImageTexture.create_from_image).
  // Statics ptrcall with a NULL instance, which the instance entry point rejects — they must
  // route through kanama_ios_godot_ptrcall_static. Byte read-back memcpy's the array once
  // C-side (the Android per-element FFI lesson, applied to this boundary).

  // Lay a ByteArray into scratch + a {count,data} descriptor for a BUILD-tagged
  // PT_PACKED_BYTE_ARRAY arg (the C dispatch builds the Godot array from it).
  // task 100 (parcel 7) — Variant / Dictionary / Array ARGUMENTS. The generated helpers lay out a
  // KanamaIosVariantArgDesc {tag, ptr} (Variant) or the task-29 entry blob (Dictionary / Array) in
  // the call's memScope and hand the pointer to the dispatch, which boxes / rebuilds the Godot
  // value
  // for the call and destroys it afterwards. Supported inside a Variant: null, Boolean, Int/Long,
  // Float/Double, String, NodePath, Vector2/2i/3, Color, RID, GodotObject / MemorySegment handle,
  // and ONE level of Map<String, *> / List<*> whose values are scalars. Supported inside a
  // Dictionary / Array argument: scalars only; a nested container or any other Kotlin object throws
  // (IosReturnContainerScratch.taggedValue strict mode) rather than passing nil.
  internal fun MemScope.packVariantDesc(value: Any?): CPointer<KanamaIosVariantArgDesc> {
    // The struct's own `ptr` FIELD shadows kotlinx.cinterop's `.ptr` on the pointed value, so keep
    // the pointer to the descriptor from the allocation and touch fields through `pointed`.
    val descPtr = allocArray<KanamaIosVariantArgDesc>(1)
    val desc = descPtr.pointed
    when (value) {
      null -> {
        desc.tag = PT_VOID
        desc.ptr = null
      }
      is Boolean -> {
        val c = alloc<ByteVar>()
        c.value = if (value) 1 else 0
        desc.tag = PT_BOOL
        desc.ptr = c.ptr
      }
      is Int -> {
        val c = alloc<LongVar>()
        c.value = value.toLong()
        desc.tag = PT_INT64
        desc.ptr = c.ptr
      }
      is Long -> {
        val c = alloc<LongVar>()
        c.value = value
        desc.tag = PT_INT64
        desc.ptr = c.ptr
      }
      // A typed Godot enum / bitfield boxed through an `Any?` argument is its INT (task 128 A).
      is GodotEnumValue -> {
        val c = alloc<LongVar>()
        c.value = value.value
        desc.tag = PT_INT64
        desc.ptr = c.ptr
      }
      is Float -> {
        val c = alloc<DoubleVar>()
        c.value = value.toDouble()
        desc.tag = PT_FLOAT64
        desc.ptr = c.ptr
      }
      is Double -> {
        val c = alloc<DoubleVar>()
        c.value = value
        desc.tag = PT_FLOAT64
        desc.ptr = c.ptr
      }
      is String -> {
        desc.tag = PT_STRING
        desc.ptr = value.cstr.ptr
      }
      is NodePath -> {
        desc.tag = PT_NODE_PATH
        desc.ptr = value.path.cstr.ptr
      }
      is Vector2 -> {
        val c = allocArray<GodotRealVar>(2)
        c[0] = value.rawX
        c[1] = value.rawY
        desc.tag = PT_VECTOR2
        desc.ptr = c
      }
      is Vector2i -> {
        val c = allocArray<IntVar>(2)
        c[0] = value.x
        c[1] = value.y
        desc.tag = PT_VECTOR2I
        desc.ptr = c
      }
      is Vector3 -> {
        val c = allocArray<GodotRealVar>(3)
        c[0] = value.rawX
        c[1] = value.rawY
        c[2] = value.rawZ
        desc.tag = PT_VECTOR3
        desc.ptr = c
      }
      is Color -> {
        val c = allocArray<FloatVar>(4)
        c[0] = value.rawR
        c[1] = value.rawG
        c[2] = value.rawB
        c[3] = value.rawA
        desc.tag = PT_COLOR
        desc.ptr = c
      }
      is RID -> {
        val c = alloc<LongVar>()
        c.value = value.value
        desc.tag = PT_RID
        desc.ptr = c.ptr
      }
      is GodotObject -> {
        val c = alloc<LongVar>()
        // A Variant value: a freed wrapper is nil, silently (task 131 item 2).
        c.value = FreedObjectChecks.valueSegment(value).address()
        desc.tag = PT_OBJECT
        desc.ptr = c.ptr
      }
      is MemorySegment -> {
        val c = alloc<LongVar>()
        c.value = value.address()
        desc.tag = PT_OBJECT
        desc.ptr = c.ptr
      }
      is Map<*, *> -> {
        desc.tag = PT_DICTIONARY
        desc.ptr =
          IosReturnContainerScratch.encodeDictionary(
            value,
            { n -> allocArray<ByteVar>(n) },
            strict = true,
          )
      }
      is List<*> -> {
        desc.tag = PT_ARRAY
        desc.ptr =
          IosReturnContainerScratch.encodeArray(
            value,
            { n -> allocArray<ByteVar>(n) },
            strict = true,
          )
      }
      // A PackedByteArray Variant value (Object.set, set_meta), as desktop's initVariantFromAny.
      is ByteArray -> {
        desc.tag = PT_PACKED_BYTE_ARRAY
        desc.ptr = packByteDesc(value)
      }
      // Task 133 value types (Vector3i ... Projection): raw Godot bytes, boxed by the shim.
      else -> {
        val raw = allocIosRawValue()
        val tag = encodeIosRawValue(value, raw)
        if (tag >= 0) {
          desc.tag = tag
          desc.ptr = raw
          return descPtr
        }
        error(
          "iOS: unsupported Variant argument type " +
            (value::class.simpleName ?: "<anonymous>") +
            " (scalars, String/NodePath, Vector2/2i/3, Color, RID, ByteArray, the value types " +
            "Vector3i ... Projection, object handles and nested Map / List up to 8 levels are " +
            "marshalled)"
        )
      }
    }
    return descPtr
  }

  internal fun MemScope.packDictionaryBlob(map: Map<String, Any?>): CPointer<ByteVar> =
    IosReturnContainerScratch.encodeDictionary(map, { n -> allocArray<ByteVar>(n) }, strict = true)

  internal fun MemScope.packArrayBlob(values: List<Any?>): CPointer<ByteVar> =
    IosReturnContainerScratch.encodeArray(values, { n -> allocArray<ByteVar>(n) }, strict = true)

  internal fun MemScope.packByteDesc(bytes: ByteArray): CPointer<KanamaIosPackedArgDesc> {
    val n = bytes.size
    val buf = allocArray<ByteVar>(if (n > 0) n else 1)
    for (i in 0 until n) buf[i] = bytes[i]
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = n.toLong()
    desc.data = buf.reinterpret()
    return desc.ptr
  }

  // PackedByteArray return on any arg shape through the single-call packed entry (task 129 D): the
  // method runs once. A positive sizeHint (Image.getDataSize, FileAccess.get_size) sizes the inline
  // buffer; a longer array is parked C-side and drained whole, never re-requested.
  private fun retByteArray(
    methodBind: MemorySegment,
    instance: MemorySegment,
    sizeHint: Long,
    argBuilder: MemScope.() -> Triple<CPointer<IntVar>?, CPointer<COpaquePointerVar>?, Int>,
  ): ByteArray = memScoped {
    val (types, ptrs, argc) = argBuilder()
    val (buf, n) =
      ptrcallPackedElements(
        methodBind,
        instance,
        types,
        ptrs,
        argc,
        VT_PACKED_BYTE_ARRAY,
        1,
        if (sizeHint > 0L) sizeHint else PACKED_INLINE_CAP,
      )
    if (n == 0) ByteArray(0) else buf.readBytes(n)
  }

  actual fun ptrcallNoArgsRetByteArray(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): ByteArray = ptrcallNoArgsRetByteArray(methodBind, instance, -1L)

  // iOS-ONLY overload. The two-argument helper above is the shape the shared wrapper tree calls and
  // the one desktop declares, so it is the one that matches an `expect` member (task 104 step 3);
  // this one takes the caller's known byte count so the read-back can size its buffer in one go
  // instead of growing it (Image.getData passes get_data_size()). An `actual object` may carry
  // extra members, so it stays — but it cannot be a DEFAULT on the shape above: that would make the
  // arity differ from desktop's, and an `actual` may not restate defaults either.
  fun ptrcallNoArgsRetByteArray(
    methodBind: MemorySegment,
    instance: MemorySegment,
    sizeHint: Long,
  ): ByteArray =
    retByteArray(methodBind, instance, sizeHint) {
      Triple<CPointer<IntVar>?, CPointer<COpaquePointerVar>?, Int>(null, null, 0)
    }

  actual fun ptrcallWithByteArrayArgRetLong(
    methodBind: MemorySegment,
    instance: MemorySegment,
    value: ByteArray,
  ): Long = memScoped {
    val ret = alloc<LongVar>()
    ret.value = 0
    val types = allocArray<IntVar>(1)
    types[0] = PT_PACKED_BYTE_ARRAY
    val ptrs = allocArray<COpaquePointerVar>(1)
    ptrs[0] = packByteDesc(value).reinterpret<CPointed>()
    ptrcallDispatch(methodBind.address(), instance.address(), types, ptrs, 1, PT_INT64, ret.ptr)
    ret.value
  }

  fun ptrcallStaticWithObjectArgRetObject(
    methodBind: MemorySegment,
    a0: MemorySegment,
  ): MemorySegment = memScoped {
    val ret = alloc<LongVar>()
    ret.value = 0
    val c0 = alloc<LongVar>()
    c0.value = a0.address()
    val types = allocArray<IntVar>(1)
    types[0] = PT_OBJECT
    val ptrs = allocArray<COpaquePointerVar>(1)
    ptrs[0] = c0.ptr.reinterpret<CPointed>()
    kanama_ios_godot_ptrcall_static(methodBind.address(), types, ptrs, 1, PT_OBJECT, ret.ptr)
    MemorySegment.ofAddress(ret.value)
  }

  fun ptrcallStaticWithStringAndLongArgsRetObject(
    methodBind: MemorySegment,
    a0: String,
    a1: Long,
  ): MemorySegment = memScoped {
    val ret = alloc<LongVar>()
    ret.value = 0
    val c1 = alloc<LongVar>()
    c1.value = a1
    val types = allocArray<IntVar>(2)
    types[0] = PT_STRING
    types[1] = PT_INT64
    val ptrs = allocArray<COpaquePointerVar>(2)
    ptrs[0] = a0.cstr.ptr.reinterpret<CPointed>()
    ptrs[1] = c1.ptr.reinterpret<CPointed>()
    kanama_ios_godot_ptrcall_static(methodBind.address(), types, ptrs, 2, PT_OBJECT, ret.ptr)
    MemorySegment.ofAddress(ret.value)
  }

  fun ptrcallStaticWithStringArgRetLong(methodBind: MemorySegment, a0: String): Long = memScoped {
    val ret = alloc<LongVar>()
    ret.value = 0
    val types = allocArray<IntVar>(1)
    types[0] = PT_STRING
    val ptrs = allocArray<COpaquePointerVar>(1)
    ptrs[0] = a0.cstr.ptr.reinterpret<CPointed>()
    kanama_ios_godot_ptrcall_static(methodBind.address(), types, ptrs, 1, PT_INT64, ret.ptr)
    ret.value
  }

  fun ptrcallStaticWithStringArgRetByteArray(
    methodBind: MemorySegment,
    a0: String,
    sizeHint: Long = -1L,
  ): ByteArray =
    retByteArray(methodBind, MemorySegment.NULL, sizeHint) {
      val types = allocArray<IntVar>(1)
      types[0] = PT_STRING
      val ptrs = allocArray<COpaquePointerVar>(1)
      ptrs[0] = a0.cstr.ptr.reinterpret<CPointed>()
      Triple<CPointer<IntVar>?, CPointer<COpaquePointerVar>?, Int>(types, ptrs, 1)
    }

  // Image.create_from_data(width, height, mipmaps, format, data): static, scalars + bytes.
  fun ptrcallStaticWithTwoLongBoolLongByteArrayArgsRetObject(
    methodBind: MemorySegment,
    a0: Long,
    a1: Long,
    a2: Boolean,
    a3: Long,
    a4: ByteArray,
  ): MemorySegment = memScoped {
    val ret = alloc<LongVar>()
    ret.value = 0
    val c0 = alloc<LongVar>()
    c0.value = a0
    val c1 = alloc<LongVar>()
    c1.value = a1
    val c2 = alloc<ByteVar>()
    c2.value = if (a2) 1 else 0
    val c3 = alloc<LongVar>()
    c3.value = a3
    val types = allocArray<IntVar>(5)
    types[0] = PT_INT64
    types[1] = PT_INT64
    types[2] = PT_BOOL
    types[3] = PT_INT64
    types[4] = PT_PACKED_BYTE_ARRAY
    val ptrs = allocArray<COpaquePointerVar>(5)
    ptrs[0] = c0.ptr.reinterpret<CPointed>()
    ptrs[1] = c1.ptr.reinterpret<CPointed>()
    ptrs[2] = c2.ptr.reinterpret<CPointed>()
    ptrs[3] = c3.ptr.reinterpret<CPointed>()
    ptrs[4] = packByteDesc(a4).reinterpret<CPointed>()
    kanama_ios_godot_ptrcall_static(methodBind.address(), types, ptrs, 5, PT_OBJECT, ret.ptr)
    MemorySegment.ofAddress(ret.value)
  }

  // Typed builtin Array returns (Phase 2.7g): a no-arg getter returning Array[StringName] /
  // Array[NodePath] / Array[int] / Array[Plane], read back through the single-call typed-array blob
  // every arg shape uses (task 129 D; the old no-arg blob ran the method twice).
  private fun <T> retTypedArrayBlob(
    methodBind: MemorySegment,
    instance: MemorySegment,
    elemKind: Int,
    parse: (ByteArray, Int, Int) -> T,
  ): List<T> = memScoped { typedList(methodBind, instance, null, null, 0, elemKind, parse) }

  // Array[StringName] -> List<String> (group / animation-library name lists). Phase 2.7g.
  actual fun ptrcallNoArgsRetStringNameList(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): List<String> =
    retTypedArrayBlob(methodBind, instance, PT_STRING_NAME) { b, o, l ->
      b.decodeToString(o, o + l)
    }

  // Array[NodePath] -> List<NodePath>. Phase 2.7g.
  actual fun ptrcallNoArgsRetNodePathList(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): List<NodePath> =
    retTypedArrayBlob(methodBind, instance, PT_NODE_PATH) { b, o, l ->
      NodePath(b.decodeToString(o, o + l))
    }

  // Array[int] -> List<Long> (e.g. get_orphan_node_ids). Each record is an 8-byte int64 LE. Phase
  // 2.7g.
  actual fun ptrcallNoArgsRetLongList(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): List<Long> =
    retTypedArrayBlob(methodBind, instance, PT_INT64) { b, o, _ ->
      var v = 0L
      for (k in 7 downTo 0) v = (v shl 8) or (b[o + k].toLong() and 0xFF)
      v
    }

  private fun i32LE(b: ByteArray, o: Int): Int =
    (b[o].toInt() and 0xFF) or
      ((b[o + 1].toInt() and 0xFF) shl 8) or
      ((b[o + 2].toInt() and 0xFF) shl 16) or
      ((b[o + 3].toInt() and 0xFF) shl 24)

  private fun realLE(b: ByteArray, o: Int): GodotRealStorage = Float.fromBits(i32LE(b, o))

  // Array[Plane] -> List<Plane> (e.g. Camera3D.get_frustum). Each record is 4 float32 LE
  // (normal.x, normal.y, normal.z, d). Phase 2.7i.
  actual fun ptrcallNoArgsRetPlaneList(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): List<Plane> =
    retTypedArrayBlob(methodBind, instance, PT_PLANE) { b, o, _ ->
      Plane.raw(Vector3.raw(realLE(b, o), realLE(b, o + 4), realLE(b, o + 8)), realLE(b, o + 12))
    }

  // Generic Array -> List<Any?> (Phase 2.7j), through the single-call container blob every arg
  // shape uses (task 129 D; the old variant-array blob ran the method twice). Args are laid out by
  // the caller's layoutArgs lambda.
  private fun retVariantArrayBlob(
    methodBind: MemorySegment,
    instance: MemorySegment,
    layoutArgs: MemScope.() -> Triple<CPointer<IntVar>?, CPointer<COpaquePointerVar>?, Int>,
  ): List<Any?> = memScoped {
    val (types, ptrs, argc) = layoutArgs()
    val bytes = ptrcallContainerBlob(methodBind, instance, types, ptrs, argc, VT_ARRAY)
    if (bytes.size < 4) emptyList() else ContainerBlob(bytes, 0).array()
  }

  actual fun ptrcallNoArgsRetArray(methodBind: MemorySegment, instance: MemorySegment): List<Any?> =
    retVariantArrayBlob(methodBind, instance) {
      Triple<CPointer<IntVar>?, CPointer<COpaquePointerVar>?, Int>(null, null, 0)
    }

  actual fun ptrcallWithNodePathArgRetArray(
    methodBind: MemorySegment,
    instance: MemorySegment,
    path: NodePath,
  ): List<Any?> =
    retVariantArrayBlob(methodBind, instance) {
      val types = allocArray<IntVar>(1)
      types[0] = PT_NODE_PATH
      val ptrs = allocArray<COpaquePointerVar>(1)
      ptrs[0] = path.path.cstr.ptr.reinterpret<CPointed>()
      Triple<CPointer<IntVar>?, CPointer<COpaquePointerVar>?, Int>(types, ptrs, 1)
    }

  // PackedVector2Array arg via the generic dispatch: pack the List into a flat float buffer
  // (2 per Vector2), hand a {count,data} descriptor to the dispatch under PT_PACKED_VECTOR2_ARRAY;
  // the C side builds the Godot array (constructor + push_back) and destroys it after the call.
  actual fun ptrcallWithPackedVector2ListArg(
    methodBind: MemorySegment,
    instance: MemorySegment,
    values: List<Vector2>,
  ) = memScoped {
    val n = values.size
    val floats = allocArray<GodotRealVar>(if (n > 0) n * 2 else 1)
    for (i in 0 until n) {
      floats[i * 2] = values[i].rawX
      floats[i * 2 + 1] = values[i].rawY
    }
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = n.toLong()
    desc.data = floats.reinterpret()
    val types = allocArray<IntVar>(1)
    types[0] = PT_PACKED_VECTOR2_ARRAY
    val ptrs = allocArray<COpaquePointerVar>(1)
    ptrs[0] = desc.ptr.reinterpret<CPointed>()
    ptrcallDispatch(methodBind.address(), instance.address(), types, ptrs, 1, PT_VOID, null)
    Unit
  }

  // PackedColorArray arg via the generic dispatch (4 floats per Color element).
  actual fun ptrcallWithPackedColorListArg(
    methodBind: MemorySegment,
    instance: MemorySegment,
    values: List<Color>,
  ) = memScoped {
    val n = values.size
    val floats = allocArray<FloatVar>(if (n > 0) n * 4 else 1)
    for (i in 0 until n) {
      floats[i * 4] = values[i].rawR
      floats[i * 4 + 1] = values[i].rawG
      floats[i * 4 + 2] = values[i].rawB
      floats[i * 4 + 3] = values[i].rawA
    }
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = n.toLong()
    desc.data = floats.reinterpret()
    val types = allocArray<IntVar>(1)
    types[0] = PT_PACKED_COLOR_ARRAY
    val ptrs = allocArray<COpaquePointerVar>(1)
    ptrs[0] = desc.ptr.reinterpret<CPointed>()
    ptrcallDispatch(methodBind.address(), instance.address(), types, ptrs, 1, PT_VOID, null)
    Unit
  }

  // Lay a List<Vector2> into a flat float32 buffer + a {count,data} descriptor; returns the
  // descriptor pointer for use as a PT_PACKED_VECTOR2_ARRAY arg in a multi-arg dispatch.
  internal fun MemScope.packVector2Desc(values: List<Vector2>): CPointer<KanamaIosPackedArgDesc> {
    val n = values.size
    val floats = allocArray<GodotRealVar>(if (n > 0) n * 2 else 1)
    for (i in 0 until n) {
      floats[i * 2] = values[i].rawX
      floats[i * 2 + 1] = values[i].rawY
    }
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = n.toLong()
    desc.data = floats.reinterpret()
    return desc.ptr
  }

  internal fun MemScope.packColorDesc(values: List<Color>): CPointer<KanamaIosPackedArgDesc> {
    val n = values.size
    val floats = allocArray<FloatVar>(if (n > 0) n * 4 else 1)
    for (i in 0 until n) {
      floats[i * 4] = values[i].rawR
      floats[i * 4 + 1] = values[i].rawG
      floats[i * 4 + 2] = values[i].rawB
      floats[i * 4 + 3] = values[i].rawA
    }
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = n.toLong()
    desc.data = floats.reinterpret()
    return desc.ptr
  }

  // task 100 (parcel 4) — descriptor helpers for the remaining BUILD-tagged Packed*Array args.
  // Element layouts match kanama_ios_build_packed_arg: int32 4 B, int64 8 B, float32 4 B,
  // float64 8 B, Vector3 3 × float32; PackedStringArray is the [int32 count]([int32 len][utf8])*
  // blob kanama_ios_build_packed_string_array_from_blob consumes (desc.data points at it,
  // desc.count is the string count). The generated helpers call these; the dispatch builds the
  // Godot array from the descriptor and destroys it after the call.
  internal fun MemScope.packInt32Desc(values: List<Int>): CPointer<KanamaIosPackedArgDesc> {
    val n = values.size
    val buf = allocArray<IntVar>(if (n > 0) n else 1)
    for (i in 0 until n) buf[i] = values[i]
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = n.toLong()
    desc.data = buf.reinterpret()
    return desc.ptr
  }

  internal fun MemScope.packInt64Desc(values: List<Long>): CPointer<KanamaIosPackedArgDesc> {
    val n = values.size
    val buf = allocArray<LongVar>(if (n > 0) n else 1)
    for (i in 0 until n) buf[i] = values[i]
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = n.toLong()
    desc.data = buf.reinterpret()
    return desc.ptr
  }

  internal fun MemScope.packFloat32Desc(values: List<Float>): CPointer<KanamaIosPackedArgDesc> {
    val n = values.size
    val buf = allocArray<FloatVar>(if (n > 0) n else 1)
    for (i in 0 until n) buf[i] = values[i]
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = n.toLong()
    desc.data = buf.reinterpret()
    return desc.ptr
  }

  internal fun MemScope.packFloat64Desc(values: List<Double>): CPointer<KanamaIosPackedArgDesc> {
    val n = values.size
    val buf = allocArray<DoubleVar>(if (n > 0) n else 1)
    for (i in 0 until n) buf[i] = values[i]
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = n.toLong()
    desc.data = buf.reinterpret()
    return desc.ptr
  }

  internal fun MemScope.packVector3Desc(values: List<Vector3>): CPointer<KanamaIosPackedArgDesc> {
    val n = values.size
    val floats = allocArray<FloatVar>(if (n > 0) n * 3 else 1)
    for (i in 0 until n) {
      floats[i * 3] = values[i].rawX
      floats[i * 3 + 1] = values[i].rawY
      floats[i * 3 + 2] = values[i].rawZ
    }
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = n.toLong()
    desc.data = floats.reinterpret()
    return desc.ptr
  }

  internal fun MemScope.packStringDesc(values: List<String>): CPointer<KanamaIosPackedArgDesc> {
    val encoded = values.map { it.encodeToByteArray() }
    val total = 4 + encoded.sumOf { 4 + it.size }
    val blob = allocArray<ByteVar>(total)
    var off = 0
    fun putInt(v: Int) {
      blob[off] = (v and 0xff).toByte()
      blob[off + 1] = ((v ushr 8) and 0xff).toByte()
      blob[off + 2] = ((v ushr 16) and 0xff).toByte()
      blob[off + 3] = ((v ushr 24) and 0xff).toByte()
      off += 4
    }
    putInt(encoded.size)
    for (bytes in encoded) {
      putInt(bytes.size)
      for (b in bytes) {
        blob[off] = b
        off += 1
      }
    }
    val desc = alloc<KanamaIosPackedArgDesc>()
    desc.count = encoded.size.toLong()
    desc.data = blob.reinterpret()
    return desc.ptr
  }

  // task 100 (parcel 8) — typed-Array ARGUMENTS. Each element is written as a tagged record
  // ([int32 tag][int32 len][bytes], the task-29 container layout the C blob boxer reads); the
  // descriptor carries the element's Variant.Type for array_set_typed (+ the class name for
  // object elements). The dispatch builds the typed Array before the ptrcall and destroys it after.
  private fun MemScope.packTypedArrayDesc(
    variantType: Int,
    className: String?,
    elements: List<Pair<Int, ByteArray>>,
  ): CPointer<KanamaIosTypedArrayArgDesc> {
    var total = 4
    for ((_, bytes) in elements) total += 8 + bytes.size
    val blob = allocArray<ByteVar>(total)
    var off = 0
    fun putInt32(v: Int) {
      blob[off] = (v and 0xFF).toByte()
      blob[off + 1] = ((v ushr 8) and 0xFF).toByte()
      blob[off + 2] = ((v ushr 16) and 0xFF).toByte()
      blob[off + 3] = ((v ushr 24) and 0xFF).toByte()
      off += 4
    }
    putInt32(elements.size)
    for ((tag, bytes) in elements) {
      putInt32(tag)
      putInt32(bytes.size)
      for (b in bytes) {
        blob[off] = b
        off += 1
      }
    }
    val desc = alloc<KanamaIosTypedArrayArgDesc>()
    desc.variant_type = variantType
    desc.class_name = className?.cstr?.getPointer(this)
    desc.blob = blob.reinterpret()
    return desc.ptr
  }

  private fun int64Bytes(v: Long): ByteArray =
    ByteArray(8) { ((v ushr (8 * it)) and 0xFF).toByte() }

  private fun int32Bytes(vararg vs: Int): ByteArray {
    val out = ByteArray(4 * vs.size)
    for ((i, v) in vs.withIndex()) for (k in 0 until 4) out[4 * i + k] =
      ((v ushr (8 * k)) and 0xFF).toByte()
    return out
  }

  private fun float32Bytes(vararg vs: Float): ByteArray {
    val out = ByteArray(4 * vs.size)
    for ((i, v) in vs.withIndex()) {
      val bits = v.toRawBits()
      for (k in 0 until 4) out[4 * i + k] = ((bits ushr (8 * k)) and 0xFF).toByte()
    }
    return out
  }

  fun MemScope.packTypedRIDArrayDesc(values: List<RID>): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(VT_RID_TYPE, null, values.map { Pair(PT_RID, int64Bytes(it.value)) })

  fun MemScope.packTypedLongArrayDesc(values: List<Long>): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(VT_INT, null, values.map { Pair(PT_INT64, int64Bytes(it)) })

  fun MemScope.packTypedStringArrayDesc(
    values: List<String>
  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(VT_STRING_TYPE, null, values.map { Pair(PT_STRING, it.encodeToByteArray()) })

  fun MemScope.packTypedStringNameArrayDesc(
    values: List<String>
  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_STRING_NAME_TYPE,
      null,
      values.map { Pair(PT_STRING_NAME, it.encodeToByteArray()) },
    )

  fun MemScope.packTypedNodePathArrayDesc(
    values: List<NodePath>
  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_NODE_PATH_TYPE,
      null,
      values.map { Pair(PT_NODE_PATH, it.path.encodeToByteArray()) },
    )

  fun MemScope.packTypedVector2iArrayDesc(
    values: List<Vector2i>
  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_VECTOR2I_TYPE,
      null,
      values.map { Pair(PT_VECTOR2I, int32Bytes(it.x, it.y)) },
    )

  fun MemScope.packTypedTransform3DArrayDesc(
    values: List<Transform3D>
  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_TRANSFORM3D_TYPE,
      null,
      values.map { t ->
        // 9 basis components column-major (ios_arg_layout's Transform3D layout) + 3 origin.
        Pair(
          PT_TRANSFORM3D,
          float32Bytes(
            t.basis.x.rawX,
            t.basis.y.rawX,
            t.basis.z.rawX,
            t.basis.x.rawY,
            t.basis.y.rawY,
            t.basis.z.rawY,
            t.basis.x.rawZ,
            t.basis.y.rawZ,
            t.basis.z.rawZ,
            t.origin.rawX,
            t.origin.rawY,
            t.origin.rawZ,
          ),
        )
      },
    )

  fun MemScope.packTypedPlaneArrayDesc(values: List<Plane>): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_PLANE_TYPE,
      null,
      values.map {
        Pair(PT_PLANE, float32Bytes(it.normal.rawX, it.normal.rawY, it.normal.rawZ, it.rawD))
      },
    )

  fun MemScope.packTypedPackedVector2ListArrayDesc(
    values: List<List<Vector2>>
  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_PACKED_VECTOR2_ARRAY_TYPE,
      null,
      values.map { inner ->
        val floats = FloatArray(inner.size * 2)
        for ((i, v) in inner.withIndex()) {
          floats[2 * i] = v.rawX
          floats[2 * i + 1] = v.rawY
        }
        Pair(PT_PACKED_VECTOR2_ARRAY, int32Bytes(inner.size) + float32Bytes(*floats))
      },
    )

  // Array[<Object subclass>] arguments are packed UNTYPED (Variant.Type NIL, no class name): one
  // generated helper shape serves every element class (GLTFState.set_nodes and the CompositorEffect
  // setters share ptrcallWithObjectListArg, as on desktop, whose initArrayOfObjects is untyped
  // too),
  // and the engine's TypedArray<T> conversion at the ptrcall boundary validates each element
  // against
  // the parameter's class. Typing the Array with any one class here made every other caller of the
  // same shape hand the engine an Array[WrongClass] that it refuses (parcel-8 device gate finding).
  // `List<*>`, matching desktop's `BuiltinTypes.initArrayOfObjects`: the generated helpers that
  // take an Array[Object subclass] argument are `actual` members of an `expect object` since task
  // 104 step 3 parcel C', so their parameter types must be desktop's. The elements are wrapper
  // instances by construction (the generated wrapper passes `List<Element>`); a non-wrapper element
  // is a generator bug, and the cast says so at the seam instead of silently pushing a null handle.
  fun MemScope.packTypedObjectArrayDesc(values: List<*>): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_NIL_TYPE,
      null,
      values.map { value ->
        val element =
          checkNotNull(value as? GodotObject) {
            "typed object array element is not a GodotObject wrapper: $value"
          }
        // An Array element is a value: a freed wrapper is a null element (task 131 item 2).
        Pair(PT_OBJECT, int64Bytes(FreedObjectChecks.valueSegment(element).address()))
      },
    )

  // task 100 (parcel 10) — typed arrays whose ELEMENTS are containers or packed arrays. A
  // Dictionary / Array element is a whole task-29 blob (scalars, ByteArrays and nested containers
  // inside, one level:
  // the strict encoder throws on anything deeper), a PackedByteArray element is its raw bytes and
  // a PackedStringArray element is the task-13 string blob; the dispatch's blob boxer rebuilds
  // each element before push_back. One helper per argument layout, never per element content.
  fun MemScope.packTypedDictionaryArrayDesc(
    values: List<Map<String, Any?>>
  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_DICTIONARY,
      null,
      values.map {
        Pair(PT_DICTIONARY, IosReturnContainerScratch.encodeDictionaryBytes(it, strict = true))
      },
    )

  fun MemScope.packTypedArrayArrayDesc(
    values: List<List<Any?>>
  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_ARRAY,
      null,
      values.map { Pair(PT_ARRAY, IosReturnContainerScratch.encodeArrayBytes(it, strict = true)) },
    )

  fun MemScope.packTypedByteArrayArrayDesc(
    values: List<ByteArray>
  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(VT_PACKED_BYTE_ARRAY, null, values.map { Pair(PT_PACKED_BYTE_ARRAY, it) })

  fun MemScope.packTypedPackedStringListArrayDesc(
    values: List<List<String>>
  ): CPointer<KanamaIosTypedArrayArgDesc> =
    packTypedArrayDesc(
      VT_PACKED_STRING_ARRAY_TYPE,
      null,
      values.map { Pair(PT_PACKED_STRING_ARRAY, packedStringBlob(it)) },
    )

  // [int32 count]([int32 len][utf8])* — the layout kanama_ios_build_packed_string_array_from_blob
  // reads (the parcel-4 PackedStringArray argument path).
  private fun packedStringBlob(strings: List<String>): ByteArray {
    val parts = strings.map { it.encodeToByteArray() }
    var total = 4
    for (part in parts) total += 4 + part.size
    val out = ByteArray(total)
    var off = 0
    fun putInt32(v: Int) {
      for (k in 0 until 4) out[off + k] = ((v ushr (8 * k)) and 0xFF).toByte()
      off += 4
    }
    putInt32(parts.size)
    for (part in parts) {
      putInt32(part.size)
      part.copyInto(out, off)
      off += part.size
    }
    return out
  }

  private fun MemScope.colorCell(c: Color): CPointer<FloatVar> {
    val cell = allocArray<FloatVar>(4)
