    val types = allocArray<IntVar>(if (n > 0) n else 1)
    val ptrs = allocArray<COpaquePointerVar>(if (n > 0) n else 1)
    for (i in 0 until n) {
      cells[i] = objectArgs[i].address()
      types[i] = PT_OBJECT
      ptrs[i] = (cells + i)!!.reinterpret<CPointed>()
