    Unit
  }

  // PhysicsDirectSpaceState3D.intersect_ray: (query object arg) -> the result Dictionary decoded
  // into a Map. Empty map = no hit. "collider" is a raw object handle (MemorySegment; 0 dropped) —
  // the api layer wraps it as GodotObject. "position"/"normal" are Vector3; "collider_id"/"shape"
  // Long.
  fun ptrcallIntersectRay(
    methodBind: MemorySegment,
    instance: MemorySegment,
    query: MemorySegment,
  ): Map<String, Any?> = memScoped {
    val cells = allocArray<LongVar>(1)
    cells[0] = query.address()
    val types = allocArray<IntVar>(1)
    types[0] = PT_OBJECT
    val ptrs = allocArray<COpaquePointerVar>(1)
    ptrs[0] = cells.reinterpret<CPointed>()
    val buf = allocArray<ByteVar>(64)
    val total =
      ptrcallRetRaycastDictDispatch(
        methodBind.address(),
        instance.address(),
        types,
        ptrs,
        1,
        buf,
        64L,
      )
    if (total < 52L) {
      emptyMap()
    } else {
      val bytes = buf.readBytes(total.toInt())
      fun i32(o: Int): Int =
        (bytes[o].toInt() and 0xFF) or
          ((bytes[o + 1].toInt() and 0xFF) shl 8) or
          ((bytes[o + 2].toInt() and 0xFF) shl 16) or
          ((bytes[o + 3].toInt() and 0xFF) shl 24)
      fun i64(o: Int): Long {
        var v = 0L
        for (k in 7 downTo 0) v = (v shl 8) or (bytes[o + k].toLong() and 0xFF)
        return v
      }
      fun f32(o: Int): Float = Float.fromBits(i32(o))
      if (i32(0) == 0) {
        emptyMap()
      } else {
        val result = HashMap<String, Any?>()
        result["position"] = Vector3.raw(f32(4), f32(8), f32(12))
        result["normal"] = Vector3.raw(f32(16), f32(20), f32(24))
        val colliderHandle = i64(28)
        if (colliderHandle != 0L) result["collider"] = MemorySegment.ofAddress(colliderHandle)
        result["collider_id"] = i64(36)
        result["shape"] = i64(44)
        result
      }
    }
  }

  // PhysicsRayQueryParameters3D.set_exclude(Array[RID]): pass the RID ids as a flat int64 buffer;
  // the C side builds the Godot Array of RID variants and ptrcalls the setter.
  actual fun ptrcallWithRIDListArg(
    methodBind: MemorySegment,
    instance: MemorySegment,
    values: List<RID>,
  ) = memScoped {
    val n = values.size
    val arr = allocArray<LongVar>(if (n > 0) n else 1)
    for (i in 0 until n) arr[i] = values[i].value
    ptrcallWithRidArrayArgDispatch(methodBind.address(), instance.address(), arr, n)
    Unit
  }

  // ResourceLoader.load_threaded_get_status(path, progress): the C side supplies the progress
  // out-Array and reads back element 0. Returns status (-1 on error) to progress [0,1].
  actual fun ptrcallLoadStatusWithProgress(
    methodBind: MemorySegment,
    instance: MemorySegment,
    path: String,
  ): Pair<Long, Double> = memScoped {
    val progress = alloc<DoubleVar>()
    val status =
      ptrcallLoadStatusWithProgressDispatch(
        methodBind.address(),
        instance.address(),
        path,
        progress.ptr,
      )
    status to progress.value
  }

  // Shared scalar decode for a Variant return delivered through the (out_int, out_double,
  // out_str) triple — by kanama_ios_godot_object_call ([callWithVariantArgs]), by
  // kanama_ios_godot_ptrcall_ret_variant_scalar ([ptrcallRetVariantScalar], task 100 parcel 2) and
  // by kanama_ios_godot_utility_call ([UtilityCalls], task 129 B).
  internal fun MemScope.decodeVariantScalarReturn(
    retType: Int,
    outInt: LongVar,
    outDouble: DoubleVar,
    outStr: CPointer<ByteVar>,
    strBufSize: Long,
    outStrLen: LongVar,
    outIsRefCounted: IntVar?,
  ): Any? =
    when (retType) {
      VT_BOOL -> outInt.value != 0L
      VT_INT -> outInt.value
      VT_FLOAT -> outDouble.value
      VT_STRING,
      VT_STRING_NAME,
      VT_NODE_PATH -> {
        // StringName/NodePath decode to utf8 in out_str (the C side builds String(from:…)). A
        // StringName surfaces as its String and a NodePath as a NodePath, as desktop's
        // variantToScalar does (a NodePath property read through Object.get was a String on iOS).
        // A value longer than the buffer was parked C-side (kanama_ios_emit_utf8_return): drain it
        // whole.
        val len = outStrLen.value
        val text =
          when {
            len <= 0L -> ""
            len <= strBufSize -> outStr.readBytes(len.toInt()).decodeToString()
            else -> {
              val full = allocArray<ByteVar>(len)
              val got = kanama_ios_godot_take_pending_utf8(full, len)
              if (got <= 0L) "" else full.readBytes(minOf(got, len).toInt()).decodeToString()
            }
          }
        if (retType == VT_NODE_PATH) NodePath(text) else text
      }
      // The C side hands a RID's 64-bit id back in out_int (Object.get of a RID property).
      VT_RID_TYPE -> RID(outInt.value)
      // A Variant Object return is a GodotObject wrapper (RefCounted when the engine flagged the
      // handle as ref-counted and the caller owns it), the desktop contract. Until task 115 the
      // non-ref-counted case surfaced the raw MemorySegment, so `call("get", "shooter") as?
      // GodotObject` was null on iOS while desktop returned the node.
      VT_OBJECT ->
        if (outInt.value != 0L) {
          val handle = GodotHandle(MemorySegment.ofAddress(outInt.value))
          if (outIsRefCounted != null && outIsRefCounted.value != 0)
            RefCounted.owned(RefCounted(handle))
          else GodotObject(handle)
        } else {
          null
        }
      // task 121 — container returns arrive as one self-describing blob record in out_str (parked
      // C-side and drained whole when longer than the inline buffer), decoded by the same reader
      // the parcel-6 container ptrcalls use. Before, these surfaced null.
      VT_ARRAY,
      VT_DICTIONARY,
      VT_PACKED_BYTE_ARRAY,
      VT_PACKED_INT32_ARRAY,
      VT_PACKED_INT64_ARRAY,
      VT_PACKED_FLOAT32_ARRAY,
      VT_PACKED_FLOAT64_ARRAY,
      VT_PACKED_VECTOR2_ARRAY,
      VT_PACKED_VECTOR3_ARRAY,
      VT_PACKED_COLOR_ARRAY,
      VT_PACKED_VECTOR4_ARRAY,
      VT_PACKED_STRING_ARRAY_TYPE -> {
        val len = outStrLen.value
        val bytes =
          when {
            len < 8L -> ByteArray(0) // a record header alone is 8 bytes
            len <= strBufSize -> outStr.readBytes(len.toInt())
            else -> {
              val full = allocArray<ByteVar>(len)
              val got = kanama_ios_godot_take_pending_container_blob(full, len)
              if (got < 8L) ByteArray(0) else full.readBytes(minOf(got, len).toInt())
            }
          }
        if (bytes.size < 8) null else ContainerBlob(bytes, 0).record()
      }
      // Small fixed-size returns arrive as raw component bytes in out_str (see
      // kanama_ios_godot_object_call); zero length = the C side could not decode.
      VT_VECTOR2 ->
        if (outStrLen.value >= 8L) {
          val b = outStr.readBytes(8)
          Vector2.raw(realLE(b, 0), realLE(b, 4))
        } else null
      VT_VECTOR2I ->
        if (outStrLen.value >= 8L) {
          val b = outStr.readBytes(8)
          Vector2i(i32LE(b, 0), i32LE(b, 4))
        } else null
      VT_VECTOR3 ->
        if (outStrLen.value >= 12L) {
          val b = outStr.readBytes(12)
          Vector3.raw(realLE(b, 0), realLE(b, 4), realLE(b, 8))
        } else null
      VT_COLOR ->
        if (outStrLen.value >= 16L) {
          val b = outStr.readBytes(16)
          Color.raw(
            Float.fromBits(i32LE(b, 0)),
            Float.fromBits(i32LE(b, 4)),
            Float.fromBits(i32LE(b, 8)),
            Float.fromBits(i32LE(b, 12)),
          )
        } else null
      // The raw value kinds (Vector3i ... Projection) arrive as their Godot bytes in out_str (task
      // 129 B review); zero length = the C side could not decode.
      else ->
        if (outStrLen.value > 0L) net.multigesture.kanama.ios.decodeIosRawVariant(retType, outStr)
        else null
    }

  // Generic Variant Object.call dispatch (mirrors desktop ObjectCalls.callWithVariantArgs):
  // boxes each arg into a Variant C-side and invokes [methodBind] via the Variant path,
  // for the varargs / dynamic methods ptrcall can't express (Object.call, set_deferred,
  // set_custom_mouse_cursor). Returns the decoded result — scalar (Boolean/Long/Double/
  // String/GodotObject wrapper), small fixed-size (Vector2/Vector2i/Vector3/Color, raw
  // component bytes via out_str), or a container (Array -> List, Dictionary -> Map,
  // Packed*Array -> List of the element type; one blob record via out_str, task 121) — or
  // null (nil / an un-decoded return such as Transform). A String or blob longer than the 1 KiB
  // inline buffer is parked C-side and drained whole (task 100) — the value is captured once,
  // the call is not re-issued.
  // Lay out a List<Any?> into parallel PT-tag + payload-pointer arrays inside the given MemScope.
  // Shared by the Variant Object.call dispatch and the bound-Callable connect/disconnect path.
  private fun MemScope.encodeVariantArgs(
    args: List<Any?>
  ): Triple<CPointer<IntVar>, CPointer<COpaquePointerVar>, Int> {
    val n = args.size
    val tags = allocArray<IntVar>(if (n > 0) n else 1)
    val ptrs = allocArray<COpaquePointerVar>(if (n > 0) n else 1)
    for (i in 0 until n) {
      when (val a = args[i]) {
        null -> {
          tags[i] = PT_VOID
          ptrs[i] = null
        }
        is Boolean -> {
          val c = alloc<ByteVar>()
          c.value = if (a) 1 else 0
          tags[i] = PT_BOOL
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is Int -> {
          val c = alloc<LongVar>()
          c.value = a.toLong()
          tags[i] = PT_INT64
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is Long -> {
          val c = alloc<LongVar>()
          c.value = a
          tags[i] = PT_INT64
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        // A typed Godot enum / bitfield boxed through `vararg Any?` is its INT (task 128 A).
        is GodotEnumValue -> {
          val c = alloc<LongVar>()
          c.value = a.value
          tags[i] = PT_INT64
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is Float -> {
          val c = alloc<DoubleVar>()
          c.value = a.toDouble()
          tags[i] = PT_FLOAT64
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is Double -> {
          val c = alloc<DoubleVar>()
          c.value = a
          tags[i] = PT_FLOAT64
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is String -> {
          tags[i] = PT_STRING
          ptrs[i] = a.cstr.ptr.reinterpret<CPointed>()
        }
        is Vector2 -> {
          val c = allocArray<GodotRealVar>(2)
          c[0] = a.rawX
          c[1] = a.rawY
          tags[i] = PT_VECTOR2
          ptrs[i] = c.reinterpret<CPointed>()
        }
        is Vector2i -> {
          val c = allocArray<IntVar>(2)
          c[0] = a.x
          c[1] = a.y
          tags[i] = PT_VECTOR2I
          ptrs[i] = c.reinterpret<CPointed>()
        }
        is Vector3 -> {
          val c = allocArray<GodotRealVar>(3)
          c[0] = a.rawX
          c[1] = a.rawY
          c[2] = a.rawZ
          tags[i] = PT_VECTOR3
          ptrs[i] = c.reinterpret<CPointed>()
        }
        is Color -> {
          val c = allocArray<FloatVar>(4)
          c[0] = a.rawR
          c[1] = a.rawG
          c[2] = a.rawB
          c[3] = a.rawA
          tags[i] = PT_COLOR
          ptrs[i] = c.reinterpret<CPointed>()
        }
        is GodotObject -> {
          val c = alloc<LongVar>()
          // A Variant argument: a freed wrapper is nil, silently (task 131 item 2).
          c.value = FreedObjectChecks.valueSegment(a).address()
          tags[i] = PT_OBJECT
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        is MemorySegment -> {
          val c = alloc<LongVar>()
          c.value = a.address()
          tags[i] = PT_OBJECT
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        // task 122 — containers box like desktop's initVariantFromAny (List -> Array, Map ->
        // Dictionary): the return-side blob builders lay them out, strict mode throws on a value
        // type no Variant can hold, nested containers recurse.
        is List<*> -> {
          tags[i] = PT_ARRAY
          ptrs[i] = packArrayBlob(a).reinterpret<CPointed>()
        }
        is Map<*, *> -> {
          tags[i] = PT_DICTIONARY
          @Suppress("UNCHECKED_CAST")
          ptrs[i] = packDictionaryBlob(a as Map<String, Any?>).reinterpret<CPointed>()
        }
        // task 122 — NodePath and RID were accepted nested but not at the top level; the C boxer
        // already takes PT_NODE_PATH (utf8) and PT_RID (int64).
        is NodePath -> {
          tags[i] = PT_NODE_PATH
          ptrs[i] = a.path.cstr.ptr.reinterpret<CPointed>()
        }
        is RID -> {
          val c = alloc<LongVar>()
          c.value = a.value
          tags[i] = PT_RID
          ptrs[i] = c.ptr.reinterpret<CPointed>()
        }
        // A PackedByteArray argument, as desktop's initVariantFromAny takes it
        // (AudioStreamWAV.load_from_buffer, Image.create_from_data through call / callv).
        is ByteArray -> {
          tags[i] = PT_PACKED_BYTE_ARRAY
          ptrs[i] = packByteDesc(a).reinterpret<CPointed>()
        }
        // Task 133 value types (Vector3i ... Projection): raw Godot bytes, boxed by the shim
        // (kanama_ios_pt_arg_to_variant) — e.g. a script signal's emitted arguments.
        else -> {
          val raw = allocIosRawValue()
          val tag = encodeIosRawValue(a, raw)
          if (tag < 0) {
            error(
              "encodeVariantArgs: unsupported arg type " + (a::class.simpleName ?: "<anonymous>")
            )
          }
          tags[i] = tag
          ptrs[i] = raw.reinterpret<CPointed>()
        }
      }
    }
    return Triple(tags, ptrs, n)
  }

  // Object.connect(signal, Callable(target, method).bindv([boundArgs]), flags) — the bound-args
  // counterpart of IosGodot.objectConnect. Returns the Godot Error (0 == OK). Phase 4.1.
  fun connectBound(
    sourceObject: MemorySegment,
    signalName: String,
    targetObject: MemorySegment,
    method: String,
    boundArgs: List<Any?>,
    flags: Long,
  ): Long = memScoped {
    val (tags, ptrs, n) = encodeVariantArgs(boundArgs)
    kanama_ios_godot_object_connect_bound(
      sourceObject.address(),
      signalName,
      targetObject.address(),
      method,
      tags,
      ptrs,
      n,
      flags,
    )
  }

  // Symmetric teardown — rebuilds the same bound Callable so Object.disconnect matches. Phase 4.1.
  fun disconnectBound(
    sourceObject: MemorySegment,
    signalName: String,
    targetObject: MemorySegment,
    method: String,
    boundArgs: List<Any?>,
  ): Int = memScoped {
    val (tags, ptrs, n) = encodeVariantArgs(boundArgs)
    kanama_ios_godot_object_disconnect_bound(
      sourceObject.address(),
      signalName,
      targetObject.address(),
      method,
      tags,
      ptrs,
      n,
    )
  }

  // ── The root Object shapes the shared GodotObject calls that the generator does not emit (task
  // 117 P3′, D22). The other root shapes (indexed get/set, get_meta, callv, is_connected, tr/tr_n)
  // are generated below the BEGIN marker from the root `Object` methods
  // (`collect_root_object_shapes`); these four are hand-written because they delegate to the shim
  // paths iOS already proved on a device, or carry a desktop-only helper name. All four are listed
  // in IOS_HANDWRITTEN_HELPERS. None takes a guarded `method_bind` + instance C entry, so the
  // static-dispatch gate does not apply; every guarded early return they reach reports to the
  // shim's fault sink (task 124).

  // Object.connect(signal, Callable(target, method), flags) for GodotObject.connect. Delegates to
  // the shim's object+method connect (`kanama_ios_godot_object_connect`: source object, signal,
  // target object, method, flags — it builds the Callable, boxes it into a Variant and calls the
  // Object.connect bind it resolves itself, so [methodBind] is not consulted; Object.connect is the
  // only API method of this shape). Returns the Godot Error (0 == OK), -1 when the shim refused.
  // [methodBind] is not checked against the expected `Object.connect` bind (hash 1518946055): the
  // fault sink (`kanama_ios_fault`) is C-only and this file has no debug-only throwing check,
  // so an assertion here could only be `error(...)`, a release crash on a path that works.
  // The shared GodotObject is the only caller and passes its cached `Object.connect` bind.
  actual fun ptrcallWithStringNameCallableAndUInt32ArgsRetLong(
    methodBind: MemorySegment,
    instance: MemorySegment,
    name: String,
    callableObject: MemorySegment,
    callableMethod: String,
    flags: Long,
  ): Long {
    // Desktop's BuiltinTypes.requireUInt32(flags): Object.connect's flags are a Godot uint32.
    require(flags in 0L..0xffff_ffffL) {
      "Value $flags is outside Godot uint32 range 0..4294967295"
    }
    return IosGodot.objectConnect(
      instance.address(),
      name,
      callableObject.address(),
      callableMethod,
      flags,
    )
  }

  // Object.connect(signal, Callable(target, method).bindv(boundArgs), flags) for
  // GodotObject.connectBound — the existing bound-Callable path above ([connectBound]); the shim
  // resolves the Object.connect bind itself, so [methodBind] is not consulted.
  // [methodBind] is not checked against the expected `Object.connect` bind (hash 1518946055): the
  // fault sink (`kanama_ios_fault`) is C-only and this file has no debug-only throwing check,
  // so an assertion here could only be `error(...)`, a release crash on a path that works.
  // The shared GodotObject is the only caller and passes its cached `Object.connect` bind.
  actual fun ptrcallWithStringNameBoundCallableAndUInt32ArgsRetLong(
    methodBind: MemorySegment,
    instance: MemorySegment,
    name: String,
    callableObject: MemorySegment,
    callableMethod: String,
    boundArgs: List<Any?>,
    flags: Long,
  ): Long {
    // Desktop's BuiltinTypes.requireUInt32(flags): Object.connect's flags are a Godot uint32.
    require(flags in 0L..0xffff_ffffL) {
      "Value $flags is outside Godot uint32 range 0..4294967295"
    }
    return connectBound(instance, name, callableObject, callableMethod, boundArgs, flags)
  }

  // Object.disconnect(signal, Callable(target, method).bindv(boundArgs)) for
  // GodotObject.disconnectBound — the existing symmetric teardown above ([disconnectBound]); the
  // shim resolves the Object.disconnect bind itself, so [methodBind] is not consulted.
  // [methodBind] is not checked against the expected `Object.disconnect` bind (hash 1874754934):
  // the fault sink (`kanama_ios_fault`) is C-only and this file has no debug-only throwing check,
  // so an assertion here could only be `error(...)`, a release crash on a path that works.
  // The shared GodotObject is the only caller and passes its cached `Object.disconnect` bind.
  actual fun ptrcallWithStringNameAndBoundCallableArgs(
    methodBind: MemorySegment,
    instance: MemorySegment,
    name: String,
    callableObject: MemorySegment,
    callableMethod: String,
    boundArgs: List<Any?>,
  ) {
    disconnectBound(instance, name, callableObject, callableMethod, boundArgs)
  }

  // Object.add_user_signal(signal, arguments) for GodotObject.addUserSignal. The generator names
  // this shape `ptrcallWithStringAndArrayArg`; desktop's helper (and so the shared GodotObject)
  // spells it with the element type. The Array of Dictionaries travels the device-proven Variant
  // path with the method's own bind (encodeVariantArgs boxes List -> Array, Map -> Dictionary).
  actual fun ptrcallWithStringAndArrayOfDictionariesArg(
    methodBind: MemorySegment,
    instance: MemorySegment,
    message: String,
    data: List<Map<String, Any>>,
  ) {
    callWithVariantArgs(methodBind, instance, listOf(message, data))
  }

  /**
   * Generic Variant `Object.call` dispatch with the borrowed return decode — the `expect object
   * ObjectCalls` member (task 117 D27). It carries no `owned` flag: an `expect` declaration takes
   * no default argument (D24), so the owned decode is its own member, [callWithVariantArgsOwned],
   * and the flag is a private detail of this file (desktop has the same split).
   */
  actual fun callWithVariantArgs(
    methodBind: MemorySegment,
    instance: MemorySegment,
    args: List<Any?>,
  ): Any? = callWithVariantArgs(methodBind, instance, args, owned = false, ownElements = true)

  /**
   * The body of [callWithVariantArgs] and [callWithVariantArgsOwned].
   *
   * [owned] selects the return decode for calls that mint a fresh object whose sole reference lives
   * in the return Variant (e.g. ClassDB.class_call_static returning a freshly constructed
   * Resource). With the borrowed decode the C side extracts the handle and destroys the Variant,
   * freeing a RefCounted before Kotlin sees it. When [owned] is true the C side retains a
   * RefCounted result before that destroy and reports it, so it comes back as the owning
   * [RefCounted] wrapper (close() releases — task-31 return-ownership); non-RefCounted objects stay
   * borrowed.
   *
   * [ownElements] (task 122 item 3, the Object.call family: [callWithVariantArgs] and
   * [callWithVariantArgsOwned]): the C side retains every RefCounted element of a container result
   * while the return Variant still holds it, and the element comes back as an owning [RefCounted]
   * wrapper (desktop: BuiltinTypes.readVariantScalar's ownElements). The Variant getters routed
   * through here ([ptrcallNoArgsRetVariantScalar], [ptrcallWithStringNameArgRetVariantScalar]) keep
   * borrowed elements, like desktop's ptrcall getters: the object they read still holds them.
   */
  private fun callWithVariantArgs(
    methodBind: MemorySegment,
    instance: MemorySegment,
    args: List<Any?>,
    owned: Boolean,
    ownElements: Boolean,
  ): Any? = memScoped {
    val (tags, ptrs, n) = encodeVariantArgs(args)
    val outInt = alloc<LongVar>()
    val outDouble = alloc<DoubleVar>()
    val strBufSize = 1024L
    val outStr = allocArray<ByteVar>(strBufSize)
    val outStrLen = alloc<LongVar>()
    // Non-null out_is_refcounted turns on the owned retain path in the C shim; NULL
    // keeps the borrowed default, so only allocate/pass it when the caller asks.
    val outIsRefCounted = if (owned) alloc<IntVar>().also { it.value = 0 } else null
    val retType =
      objectCallDispatch(
        methodBind.address(),
        instance.address(),
        tags,
        ptrs,
        n,
        outInt.ptr,
        outDouble.ptr,
        outStr,
        strBufSize,
        outStrLen.ptr,
        outIsRefCounted?.ptr,
        ownElements,
      )
    decodeVariantScalarReturn(
      retType,
      outInt,
      outDouble,
      outStr,
      strBufSize,
      outStrLen,
      outIsRefCounted,
    )
  }

  /**
   * [callWithVariantArgs] with the owned return decode, for varargs `Object.call`s that mint a
   * fresh object whose sole reference lives in the return Variant (ClassDB.class_call_static static
   * factories). A named helper so the generator can route to it through
   * `METHOD_CALL_SHAPE_OVERRIDES`, mirroring [ptrcallWithStringNameArgRetVariantScalarOwned].
   *
   * The RefCounted ELEMENTS of a container result are owning wrappers too (task 122 item 3), as on
   * [callWithVariantArgs].
   */
  actual fun callWithVariantArgsOwned(
    methodBind: MemorySegment,
    instance: MemorySegment,
    args: List<Any?>,
  ): Any? = callWithVariantArgs(methodBind, instance, args, owned = true, ownElements = true)

  // Variant (scalar) returns route through the same device-proven Object-call decode as
  // callWithVariantArgs (kanama_ios_godot_object_call: bool/int/float/String/Object scalars, the
  // small vectors, and Array/Dictionary/Packed*Array containers since task 121). Calling the
  // method's OWN bind with Variant-encoded args is a real method invocation — Godot performs the
  // arg type coercion (e.g. String -> StringName) the call path needs. Phase 2.7e.
  actual fun ptrcallNoArgsRetVariantScalar(
    methodBind: MemorySegment,
    instance: MemorySegment,
  ): Any? =
    callWithVariantArgs(methodBind, instance, emptyList(), owned = false, ownElements = false)

  actual fun ptrcallWithStringNameArgRetVariantScalar(
    methodBind: MemorySegment,
    instance: MemorySegment,
    name: String,
  ): Any? =
    callWithVariantArgs(methodBind, instance, listOf(name), owned = false, ownElements = false)

  // task 43 — owned decode for ClassDB.instantiate: the return Variant holds the fresh
  // object's only reference and the generic object_call C path destroys it before Kotlin
  // sees the handle (use-after-free for RefCounted classes). The dedicated C entry retains
  // RefCounted results before the Variant destroy; those come back as the owning
  // RefCounted wrapper (close() releases — task-31 return-ownership). Non-RefCounted
  // results come back as a borrowed GodotObject wrapper, like every other dynamic object
  // return since task 115 (desktop: readVariantScalarOwned).
  actual fun ptrcallWithStringNameArgRetVariantScalarOwned(
    methodBind: MemorySegment,
    instance: MemorySegment,
    name: String,
  ): Any? = memScoped {
    val isRefCounted = alloc<IntVar>()
    isRefCounted.value = 0
    val handle =
      classdbInstantiateOwnedDispatch(
        methodBind.address(),
        instance.address(),
        name,
        isRefCounted.ptr,
      )
    when {
      handle == 0L -> null
      isRefCounted.value != 0 ->
        RefCounted.owned(RefCounted(GodotHandle(MemorySegment.ofAddress(handle))))
      else -> GodotObject(GodotHandle(MemorySegment.ofAddress(handle)))
    }
  }

  // Arg-bearing String returns (Phase 2.7f-1). The Object-call decode already returns a Kotlin
  // String for a STRING-typed Variant return, so these route through callWithVariantArgs with the
  // method's own bind (Variant-encoded args + STRING return decode). No new C/header — same path
  // as 2.7e. A null/non-String return (shouldn't happen for these typed methods) coerces to "".
  actual fun ptrcallWithVector2ArgRetString(
    methodBind: MemorySegment,
    instance: MemorySegment,
    value: Vector2,
  ): String = callWithVariantArgs(methodBind, instance, listOf(value)) as? String ?: ""

  actual fun ptrcallWithStringArgRetString(
    methodBind: MemorySegment,
    instance: MemorySegment,
    value: String,
  ): String = callWithVariantArgs(methodBind, instance, listOf(value)) as? String ?: ""

  actual fun ptrcallWithStringAndStringNameArgRetString(
    methodBind: MemorySegment,
    instance: MemorySegment,
    text: String,
    name: String,
  ): String = callWithVariantArgs(methodBind, instance, listOf(text, name)) as? String ?: ""

  actual fun ptrcallWithStringStringNameIntStringNameArgsRetString(
    methodBind: MemorySegment,
    instance: MemorySegment,
    text: String,
    firstName: String,
    index: Int,
    secondName: String,
  ): String =
    callWithVariantArgs(methodBind, instance, listOf(text, firstName, index, secondName)) as? String
      ?: ""

  // Arg-bearing StringName + NodePath returns (Phase 2.7f-2). The Object-call decode now converts a
  // STRING_NAME / NODE_PATH Variant return to utf8 (String(from: StringName|NodePath) C-side), so
  // these
  // route through callWithVariantArgs too. StringName returns surface as Kotlin String; NodePath
